CREATE OR REPLACE FUNCTION public.admin_expire_unpaid_store_orders()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare minutes integer:=60; affected integer;
begin
 if not private.is_store_admin() then raise exception 'ADMIN_ONLY'; end if;
 select greatest(5,coalesce((data->>'unpaid_cancellation_minutes')::integer,60))
 into minutes from public.store_settings where id=true;
 update public.store_orders
 set status='cancelled', updated_at=now()
 where status='new' and coalesce(payment_status,'') <> 'Төлбөр баталгаажсан'
   and created_at < now() - make_interval(mins=>minutes);
 get diagnostics affected = row_count;
 return affected;
end; $function$

CREATE OR REPLACE FUNCTION public.cancel_my_store_order(order_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare uid uuid=auth.uid(); affected integer;
begin
 if uid is null then raise exception 'LOGIN_REQUIRED'; end if;
 update public.store_orders
 set status='Цуцалсан', updated_at=now()
 where id=order_id and customer_id=uid and status='Шинэ'
   and coalesce(payment_status,'') <> 'Төлбөр баталгаажсан';
 get diagnostics affected = row_count;
 if affected=0 then raise exception 'ORDER_CANNOT_BE_CANCELLED'; end if;
 return (select to_jsonb(o) from public.store_orders o where o.id=order_id);
end; $function$

CREATE OR REPLACE FUNCTION public.expire_my_unpaid_store_orders()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare uid uuid=auth.uid(); minutes integer:=60; affected integer;
begin
 if uid is null then raise exception 'LOGIN_REQUIRED'; end if;
 select greatest(5,coalesce((data->>'unpaid_cancellation_minutes')::integer,60))
 into minutes from public.store_settings where id=true;
 update public.store_orders
 set status='cancelled', updated_at=now()
 where customer_id=uid and status='new'
   and coalesce(payment_status,'') <> 'Төлбөр баталгаажсан'
   and created_at < now() - make_interval(mins=>minutes);
 get diagnostics affected = row_count;
 return affected;
end; $function$

CREATE OR REPLACE FUNCTION public.store_checkout(payload jsonb, save_order boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s jsonb; cfg public.store_settings; l jsonb; p jsonb; tier_data jsonb; lines jsonb='[]'; qty integer; idx integer; sub integer=0; dd integer=0; vd integer=0; fee integer; grand integer; spent numeric; pct numeric=0; daypct numeric=0; daycat text; daynum text; uid uuid=auth.uid(); demo boolean; n text; ph text; em text; addr text; rid uuid; old public.store_orders; result jsonb;
begin
 if uid is null or not exists(select 1 from auth.users where id=uid and email_confirmed_at is not null and coalesce(is_anonymous,false)=false) then raise exception 'LOGIN_REQUIRED';end if;
 if jsonb_typeof(payload->'items') is distinct from 'array' then raise exception 'INVALID_ORDER';end if;
 if jsonb_array_length(payload->'items') not between 1 and 50 then raise exception 'INVALID_ORDER';end if;
 if (select count(distinct i->>'productId') from jsonb_array_elements(payload->'items') i)<>jsonb_array_length(payload->'items') then raise exception 'INVALID_ORDER';end if;
 select * into cfg from public.store_settings where id=true for update;s=cfg.data;
 if s is null then raise exception 'STORE_UNAVAILABLE';end if;
 demo=coalesce((s->'rules'->>'demo_mode')::boolean,true);
 em=nullif(lower(coalesce(auth.jwt()->>'email','')),'');
 if save_order then
  rid=(payload->>'requestId')::uuid;n=btrim(payload->>'name');ph=payload->>'phone';addr=btrim(payload->>'address');
  if rid is null or n is null or length(n) not between 2 and 120 or ph is null or ph !~ '^[0-9]{8}$' or addr is null or length(addr) not between 5 and 500 or length(coalesce(payload->>'note',''))>1000 then raise exception 'INVALID_ORDER';end if;
  select * into old from public.store_orders where request_id=rid;
  if found then
   if old.customer_id<>uid then raise exception 'INVALID_ORDER';end if;
   return to_jsonb(old);
  end if;
  if (select count(*) from public.store_orders where customer_id=uid and created_at>now()-interval '1 hour')>=10 then raise exception 'ORDER_LIMIT';end if;
 end if;
 select coalesce(sum(total-delivery_fee),0) into spent from public.store_orders where customer_id=uid and status='Дууссан' and not is_demo;
 if coalesce((s->'rules'->>'vip_enabled')::boolean,false) then
  select v into tier_data from jsonb_array_elements(s->'loyalty_tiers') v where coalesce((v->>'enabled')::boolean,true) and (v->>'threshold')::numeric<=spent order by (v->>'threshold')::numeric desc limit 1;
  pct=least(100,greatest(0,coalesce((tier_data->>'discount_pct')::numeric,0)));
 end if;
 daynum=extract(dow from now() at time zone 'Asia/Ulaanbaatar')::integer::text;
 if coalesce((s->'rules'->>'daily_enabled')::boolean,false) then
  daypct=least(100,greatest(0,coalesce((s->'daily_deals'->daynum->>'discount_percent')::numeric,0)));
  daycat=s->'daily_deals'->daynum->>'category';
 end if;
 for l in select * from jsonb_array_elements(payload->'items') loop
  if coalesce(l->>'quantity','') !~ '^[0-9]{1,3}$' then raise exception 'INVALID_ORDER';end if;
  qty=(l->>'quantity')::integer;if qty not between 1 and 100 then raise exception 'INVALID_ORDER';end if;
  select value,ordinality::integer-1 into p,idx from jsonb_array_elements(s->'products') with ordinality where value->>'id'=l->>'productId';
  if p is null then select value,ordinality::integer-1 into p,idx from jsonb_array_elements(s->'combos') with ordinality where value->>'id'=l->>'productId';end if;
  if p is null or not coalesce((p->>'in_stock')::boolean,true) or not coalesce((p->>'published')::boolean,true) then raise exception 'PRODUCT_UNAVAILABLE';end if;
  if (p->>'price')::integer<=0 then raise exception 'PRODUCT_UNAVAILABLE';end if;
  if not demo and coalesce((p->>'stock')::integer,0)<qty then raise exception 'OUT_OF_STOCK';end if;
  sub=sub+(p->>'price')::integer*qty;
  if daycat='all' or daycat=p->>'category' then dd=dd+round((p->>'price')::numeric*qty*daypct/100)::integer;end if;
  lines=lines||jsonb_build_array(jsonb_build_object('productId',p->>'id','title',p->>'name','quantity',qty,'price',(p->>'price')::integer));
  if save_order and not demo then
   if p ? 'category' then s=jsonb_set(s,array['products',idx::text,'stock'],to_jsonb((p->>'stock')::integer-qty));else s=jsonb_set(s,array['combos',idx::text,'stock'],to_jsonb((p->>'stock')::integer-qty));end if;
  end if;
 end loop;
 if coalesce((s->'rules'->>'stack_discounts')::boolean,false) then vd=round((sub-dd)*pct/100)::integer;
 else vd=round(sub*pct/100)::integer;if dd>=vd then vd=0;else dd=0;end if;end if;
 fee=coalesce((s->>'delivery_fee')::integer,3000);
 if (coalesce((s->'rules'->>'free_delivery_enabled')::boolean,true) and sub-dd-vd>=coalesce((s->>'free_delivery_threshold')::integer,100000)) or coalesce((tier_data->>'free_delivery')::boolean,false) then fee=0;end if;
 grand=sub-dd-vd+fee;
 if save_order and (payload->>'expectedTotal')::integer is distinct from grand then raise exception 'PRICE_CHANGED';end if;
 result=jsonb_build_object('items',lines,'subtotal',sub,'daily_discount',dd,'vip_discount',vd,'delivery_fee',fee,'total',grand,'tier',coalesce(tier_data->>'name',''),'gift',coalesce(tier_data->>'admin_gift',''),'is_demo',demo,'lifetime_spend',spent);
 if save_order then
  insert into public.customer_profiles(user_id,name,phone,address) values(uid,n,ph,addr) on conflict(user_id) do update set name=excluded.name,phone=excluded.phone,address=excluded.address;
  insert into public.store_orders(request_id,customer_id,customer_name,phone,email,address,note,items,subtotal,daily_discount,vip_discount,delivery_fee,total,tier,gift,is_demo) values(rid,uid,n,ph,em,addr,coalesce(payload->>'note',''),lines,sub,dd,vd,fee,grand,coalesce(tier_data->>'name',''),coalesce(tier_data->>'admin_gift',''),demo) returning * into old;
  if not demo then update public.store_settings set data=s,version=version+1,updated_at=now() where id=true;end if;
  result=to_jsonb(old);
 end if;
 return result;
end;$function$

CREATE OR REPLACE FUNCTION public.store_checkout_with_points(payload jsonb, save_order boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  uid uuid = auth.uid();
  requested integer = greatest(0, coalesce((payload->>'pointsToUse')::integer, 0));
  balance integer = 0;
  base_expected integer;
  usable integer;
  adjusted jsonb;
  preview jsonb;
  result jsonb;
  order_uuid uuid;
  order_total integer;
  configured_fee integer = 3000;
  applied_fee integer = 0;
  is_vehicle_pickup boolean = coalesce(payload->>'deliveryMode', '') = 'vehicle';
begin
  if uid is null then raise exception 'LOGIN_REQUIRED'; end if;
  select coalesce((data->>'delivery_fee')::integer, 3000)
    into configured_fee from public.store_settings where id=true;
  select coalesce((select available_points from public.loyalty_wallets where user_id=uid for update), 0) into balance;

  base_expected = coalesce((payload->>'expectedTotal')::integer, 0) + requested
    + case when is_vehicle_pickup then configured_fee else 0 end;
  adjusted = (payload - 'pointsToUse') || jsonb_build_object('expectedTotal', base_expected);

  -- Price, promotion and delivery calculations always come from the central catalog.
  -- The preview makes the final write use that exact authoritative amount.
  if save_order then
    preview = public.store_checkout(adjusted, false);
    adjusted = jsonb_set(adjusted, '{expectedTotal}', to_jsonb(coalesce((preview->>'total')::integer, 0)));
  end if;

  result = public.store_checkout(adjusted, save_order);
  if not save_order then return result; end if;

  order_uuid = (result->>'id')::uuid;
  applied_fee = coalesce((result->>'delivery_fee')::integer, 0);
  if is_vehicle_pickup and applied_fee > 0 then
    update public.store_orders
      set delivery_fee=0, total=total-applied_fee, updated_at=now()
      where id=order_uuid;
  end if;

  select total into order_total from public.store_orders where id=order_uuid for update;
  usable = least(requested, balance, greatest(0, order_total));
  if requested <> usable then raise exception 'POINTS_CHANGED'; end if;

  if usable > 0 then
    insert into public.loyalty_point_ledger(user_id,order_id,event_type,points)
    values(uid,order_uuid,'redeemed',-usable);
    insert into public.loyalty_wallets(user_id,available_points,lifetime_earned)
    values(uid,0,0)
    on conflict(user_id) do update
      set available_points=public.loyalty_wallets.available_points-usable,updated_at=now();
    update public.store_orders
    set points_discount=usable,total=total-usable,updated_at=now()
    where id=order_uuid;
  end if;
  return (select to_jsonb(o) from public.store_orders o where o.id=order_uuid);
end;
$function$

CREATE OR REPLACE FUNCTION public.store_order_status(p_order_id uuid, p_next_status text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  o public.store_orders;
  s jsonb;
  i jsonb;
  p jsonb;
  idx integer;
  coll text;
  earned integer;
  tier_cfg jsonb;
  best_tier jsonb;
  forced_tier_id text;
  total_spent numeric;
  cashback_pct numeric;
begin
  if not private.is_store_admin() then raise exception 'FORBIDDEN'; end if;
  if p_next_status not in ('Шинэ','Баталгаажсан','Хүргэлтэд','Дууссан','Цуцалсан') then raise exception 'INVALID_STATUS'; end if;

  select data into s from public.store_settings where id=true for update;
  select * into o from public.store_orders where id=p_order_id for update;
  if not found then raise exception 'NOT_FOUND'; end if;
  if o.status=p_next_status then return; end if;
  if o.status in ('Дууссан','Цуцалсан') then raise exception 'FINAL_STATUS'; end if;
  if p_next_status='Шинэ' then raise exception 'INVALID_TRANSITION'; end if;

  if p_next_status='Цуцалсан' and not o.is_demo then
    for i in select * from jsonb_array_elements(o.items) loop
      coll='products';
      select value,ordinality::integer-1 into p,idx from jsonb_array_elements(s->coll) with ordinality where value->>'id'=i->>'productId';
      if p is null then
        coll='combos';
        select value,ordinality::integer-1 into p,idx from jsonb_array_elements(s->coll) with ordinality where value->>'id'=i->>'productId';
      end if;
      if p is not null then s=jsonb_set(s,array[coll,idx::text,'stock'],to_jsonb((p->>'stock')::integer+(i->>'quantity')::integer)); end if;
    end loop;
    update public.store_settings set data=s,version=version+1,updated_at=now() where id=true;
  end if;

  update public.store_orders set status=p_next_status,updated_at=now() where id=p_order_id;

  if p_next_status='Дууссан' and not o.is_demo then
    tier_cfg := s->'loyalty_tiers_config';
    if tier_cfg is null or jsonb_typeof(tier_cfg) <> 'array' or jsonb_array_length(tier_cfg) = 0 then
      tier_cfg := '[
        {"id":"bronze","threshold":500000,"cashback_pct":1},
        {"id":"silver","threshold":1000000,"cashback_pct":2},
        {"id":"gold","threshold":2000000,"cashback_pct":3}
      ]'::jsonb;
    end if;

    cashback_pct := coalesce((s->>'loyalty_cashback_pct')::numeric, 1);

    if o.customer_id is not null then
      forced_tier_id := s->'loyalty_tier_overrides'->>o.customer_id::text;

      if forced_tier_id is not null then
        select value into best_tier from jsonb_array_elements(tier_cfg) value where value->>'id' = forced_tier_id;
      end if;

      if best_tier is null then
        select coalesce(sum(total),0) into total_spent from public.store_orders where customer_id = o.customer_id and status = 'Дууссан';
        select value into best_tier
          from jsonb_array_elements(tier_cfg) value
          where (value->>'threshold')::numeric <= total_spent
          order by (value->>'threshold')::numeric desc
          limit 1;
      end if;

      if best_tier is not null and (best_tier->>'cashback_pct') is not null then
        cashback_pct := (best_tier->>'cashback_pct')::numeric;
      end if;
    end if;

    earned=floor(greatest(0,o.total-o.delivery_fee)*cashback_pct/100)::integer;
    if earned > 0 then
      insert into public.loyalty_point_ledger(user_id,order_id,event_type,points)
      values(o.customer_id,o.id,'earned',earned)
      on conflict(order_id,event_type) do nothing;
      if found then
        insert into public.loyalty_wallets(user_id,available_points,lifetime_earned)
        values(o.customer_id,earned,earned)
        on conflict(user_id) do update
          set available_points=public.loyalty_wallets.available_points+earned,
              lifetime_earned=public.loyalty_wallets.lifetime_earned+earned,
              updated_at=now();
      end if;
    end if;
  end if;
end;
$function$
